from ISER import ISER
from common import auc

def build_isr(X, psi, seed, n_estimators=200, if_max_samples=256):
    """Build ISER model with given psi and seed."""
    model = ISER(max_samples=psi, n_estimators=n_estimators, if_max_samples=if_max_samples, random_state=seed)
    model.fit(X)
    return model

def scores_from_model(model, X):
    """Return dict of scores from a fitted ISER model."""
    return {
        'ISER_A': model.ISER_A(X),
        'ISER_S': model.ISER_S(X),
        'ISER_IF': model.ISER_IF(X),
    }

def run_psi_grid(X, y, psi_grid, seeds, n_estimators=200, if_max_samples=256):
    """
    For each psi in psi_grid and each seed, fit ISER and compute AUC-ROC for all three methods.
    Returns:
        results[psi] = {'mean': float, 'std': float, 'per_seed': list, 'scores': {method: list_per_seed}}
        best_psi = psi with highest mean AUC for ISER_IF (primary metric)
    """
    results = {}
    for psi in psi_grid:
        seed_results = {m: [] for m in ['ISER_A', 'ISER_S', 'ISER_IF']}
        for seed in seeds:
            model = build_isr(X, psi, seed, n_estimators, if_max_samples)
            scores = scores_from_model(model, X)
            for method in seed_results:
                seed_results[method].append(auc(y, scores[method]))
        results[psi] = {
            'mean': {m: float(np.mean(seed_results[m])) for m in seed_results},
            'std': {m: float(np.std(seed_results[m])) for m in seed_results},
            'per_seed': {m: [float(v) for v in seed_results[m]] for m in seed_results},
        }

    # Select psi that maximizes mean ISER_IF AUC
    best_psi = max(psi_grid, key=lambda p: results[p]['mean']['ISER_IF'])
    return results, best_psi

